// P1-3: item requirements (a minimum ability score) and who in the party can use an item right now.
import type { Ability } from './core.ts';
import { effectiveStat, SECONDS_PER_ROUND, type Effect, type GameClock } from './effects.ts';

export interface Requirement {
  stat: Ability;
  min: number;
  /** 'lock': unusable below the minimum. 'speed_penalty': usable, but speed drops (heavy armour). */
  onUnmet: 'lock' | 'speed_penalty';
  /** For 'speed_penalty': feet of speed lost, 10 for heavy armour. */
  penaltyFt?: number;
}

export interface RequirementItem {
  id: string;
  name: string;
  requirements: Requirement[];
}

export type AbilityScores = Record<Ability, number>;

export interface RequirementResult {
  stat: Ability;
  required: number;
  /** The score with effects. */
  actual: number;
  /** The score without effects. */
  base: number;
  met: boolean;
  /** Set when the base score fails but an effect lifts it over the line: which effect, and when it ends. */
  metByEffect?: { id: string; name: string; expiresAtSeconds?: number };
}

export interface RequirementCheck {
  usable: boolean;
  results: RequirementResult[];
  speedPenaltyFt: number;
}

/** When an effect ends on the game clock, if it has a known end. */
function endsAt(effect: Effect, clock: GameClock): number | undefined {
  if (effect.duration.kind === 'until') return effect.duration.atSeconds;
  if (effect.duration.kind === 'rounds') return clock.seconds + effect.duration.remaining * SECONDS_PER_ROUND;
  return undefined;
}

/** Checks an item's requirements against a character's scores, counting the effects active now. */
export function checkRequirements(
  item: RequirementItem,
  baseScores: AbilityScores,
  effects: readonly Effect[],
  clock: GameClock,
): RequirementCheck {
  let usable = true;
  let speedPenaltyFt = 0;
  const results = item.requirements.map((req): RequirementResult => {
    const base = baseScores[req.stat];
    const stat = effectiveStat(base, req.stat, effects, clock);
    const met = stat.value >= req.min;
    const result: RequirementResult = { stat: req.stat, required: req.min, actual: stat.value, base, met };
    if (met && base < req.min) {
      // the effect that did the most lifting gets the credit
      const best = [...stat.applied].sort((a, b) => b.value - a.value)[0];
      if (best) {
        const expiresAtSeconds = endsAt(best, clock);
        result.metByEffect = {
          id: best.id,
          name: best.name,
          ...(expiresAtSeconds !== undefined ? { expiresAtSeconds } : {}),
        };
      }
    }
    if (!met) {
      if (req.onUnmet === 'lock') usable = false;
      else speedPenaltyFt += req.penaltyFt ?? 0;
    }
    return result;
  });
  return { usable, results, speedPenaltyFt };
}

export interface PartyMember {
  id: string;
  name: string;
  baseScores: AbilityScores;
  effects: readonly Effect[];
}

export type UseState = 'usable' | 'locked' | 'usable_with_effect';

export interface WhoCanUse {
  id: string;
  name: string;
  state: UseState;
  check: RequirementCheck;
}

/** For each character: can they use the item, and is it only thanks to an effect? */
export function whoCanUse(item: RequirementItem, characters: readonly PartyMember[], clock: GameClock): WhoCanUse[] {
  return characters.map(c => {
    const check = checkRequirements(item, c.baseScores, c.effects, clock);
    const state: UseState = !check.usable
      ? 'locked'
      : check.results.some(r => r.metByEffect)
        ? 'usable_with_effect'
        : 'usable';
    return { id: c.id, name: c.name, state, check };
  });
}
